using System.Net;
using Osynix.Ats.Domain;
namespace Osynix.Ats.Services;

public static class EmailTemplateCatalog
{
    static EmailTemplate T(string key,string name,string recipient,string subject,string body)=>new(){Id=Guid.Empty,Key=key,Name=name,Recipient=recipient,Subject=subject,BodyHtml="<p>"+WebUtility.HtmlEncode(body).Replace("\n\n","</p><p>").Replace("\n","<br />")+"</p>"};
    public static List<EmailTemplate> All()=>[
        T("profiles-review","Profiles Ready For Review","Client / Hiring Manager","Osynix — Profiles Ready For Review","Hello {{ClientName}} Team,\n\n{{ProfileCount}} profiles are ready for {{PositionTitle}} (#{{PositionReference}}).\n\n{{RecruiterMessage}}\n\nReview assessment reports, add feedback, and propose interview availability:\n{{ReviewLink}}\n\nUse the same link to revisit profiles and positions shared for your client team. You may share it with authorized team members reviewing on your behalf. The same link remains available until the workspace owner replaces or revokes it. Candidate contact details and CVs are not shared."),
        T("interview-invitation","Interview Invitation","Candidate","Osynix — Interview Invitation · {{PositionTitle}}","Hello {{CandidateName}},\n\nYou Are Invited To Interview For {{PositionTitle}} With {{ClientName}}.\nPlease Review The Schedule And Joining Details Below, Then Confirm Your Availability, Decline Or Propose Another Time Using The Response Link.\n\nWe Look Forward To Speaking With You.\n\n{{InterviewScheduleAndJoiningDetails}}\n{{CandidateResponseLink}}"),
        T("team-invitation","Employer Team Invitation","Employer Team","Your Osynix Team Invitation","You have been invited to join {{EmployerName}} as a Team Member.\n\nSign in or register with {{InviteeEmail}}, verify your email, then accept this invitation:\n{{InvitationLink}}\n\nThe invitation expires in 7 days. Internal Team Members Require An Available Seat. External Freelance Recruiters Do Not Use Internal Seats."),
        T("email-verification","Email Verification Code","System","Your Osynix Verification Code","Your verification code is {{VerificationCode}}.\n\nIt expires in 10 minutes."),
        T("password-reset","Password Reset","System","Reset Your Osynix Password","Use this secure link to choose a new password:\n{{PasswordResetLink}}\n\nThe link expires in one hour."),
        T("application-received","Application Received","Candidate","We received your application for {{PositionTitle}}","Hello {{CandidateName}},\n\nThank you for applying for {{PositionTitle}} at {{CompanyName}}. We’ve received your application and the hiring team will review it.\n\nWe’ll contact you if there’s an update or if we need more information.\n\nRegards,\n{{CompanyName}} Recruitment Team"),
        T("application-review","Application Under Review","Candidate","Your application is under review","Hello {{CandidateName}},\n\nYour application for {{PositionTitle}} is under review by the hiring team.\n\nWe’ll let you know when there is an update.\n\nRegards,\n{{CompanyName}} Recruitment Team"),
        T("information-request","Request For More Information","Candidate","More information needed for your {{PositionTitle}} application","Hello {{CandidateName}},\n\nWe’re reviewing your application for {{PositionTitle}} and need a little more information:\n\n{{InformationRequested}}\n\nPlease respond by {{ResponseDate}} using this link:\n{{ResponseLink}}\n\nRegards,\n{{CompanyName}} Recruitment Team"),
        T("application-hold","Application Placed On Hold","Candidate","Update on your {{PositionTitle}} application","Hello {{CandidateName}},\n\nYour application for {{PositionTitle}} is still under consideration, but the hiring process is currently on hold.\n\nWe’ll contact you when the hiring team makes a decision.\n\nRegards,\n{{CompanyName}} Recruitment Team"),
        T("application-declined","Application Declined","Candidate","Update on your {{PositionTitle}} application","Hello {{CandidateName}},\n\nThank you for applying for {{PositionTitle}} and taking the time to speak with us.\n\nAfter review, the hiring team has decided not to proceed with your application for this position. We appreciate your interest and wish you success in your search.\n\nRegards,\n{{CompanyName}} Recruitment Team"),
        T("feedback-reminder","Client Feedback Reminder","Client / Hiring Manager","Feedback requested for {{PositionTitle}}","Hello {{ClientContactName}},\n\nThe following candidate profiles are waiting for your review for {{PositionTitle}}:\n\n{{CandidateNames}}\n\nPlease review the profiles and submit your feedback here:\n{{ReviewLink}}\n\nRegards,\n{{RecruiterName}}"),
        T("availability-request","Interview Availability Request","Client / Hiring Manager","Interview availability requested for {{PositionTitle}}","Hello {{ClientContactName}},\n\n{{CandidateName}} has been shortlisted for {{PositionTitle}}. Please share your preferred interview format and available dates and times.\n\nSubmit your availability here:\n{{ReviewLink}}\n\nThe recruiter will coordinate with the candidate and confirm the interview.\n\nRegards,\n{{RecruiterName}}"),
        T("interview-change","Interview Cancellation Or Reschedule","Candidate","Interview update for {{PositionTitle}}","Hello {{CandidateName}},\n\nThere has been a change to your interview for {{PositionTitle}}.\n\n{{InterviewUpdate}}\n\nPlease review the details and confirm your availability here:\n{{CandidateResponseLink}}\n\nIf you have questions, contact {{RecruiterName}} at {{RecruiterEmail}}."),
        T("offer-notification","Offer Notification","Candidate","An offer is ready for your review","Hello {{CandidateName}},\n\n{{CompanyName}} would like to offer you the {{PositionTitle}} position.\n\nPlease review the offer and respond by {{ResponseDate}}:\n{{OfferLink}}\n\nContact {{RecruiterName}} at {{RecruiterEmail}} if you have questions.\n\nRegards,\n{{CompanyName}} Recruitment Team"),
        T("position-assignment","External Recruiter Position Assignment","Employer Team","Position assigned to you: {{PositionTitle}}","Hello {{RecruiterName}},\n\n{{EmployerName}} has assigned you to support recruitment for {{PositionTitle}}.\n\nView the position details and submit candidates here:\n{{WorkspaceLink}}\n\nPlease use the assigned workspace for candidate submissions and updates.\n\nRegards,\n{{EmployerName}} Recruitment Team"),
        T("interview-update","Interview Status Update","Candidate","Osynix — {{InterviewEvent}} · {{PositionTitle}}","Hello {{CandidateName}},\n\n{{InterviewEvent}}\n\n{{InterviewUpdate}}"),
        T("manager-interview-update","Hiring Manager Interview Update","Client / Hiring Manager","Osynix — {{InterviewEvent}} · {{PositionTitle}}","Hello,\n\n{{InterviewEvent}} for {{CandidateName}} — {{PositionTitle}}.\n\n{{InterviewUpdate}}")
    ];
    public static readonly string[] Fields=["CandidateName","PositionTitle","PositionReference","ClientName","CompanyName","EmployerName","RecruiterName","RecruiterEmail","ClientContactName","ProfileCount","CandidateNames","RecruiterMessage","ReviewLink","InterviewScheduleAndJoiningDetails","CandidateResponseLink","InterviewEvent","InterviewUpdate","InviteeEmail","InvitationLink","InformationRequested","ResponseDate","ResponseLink","OfferLink","WorkspaceLink","VerificationCode","PasswordResetLink"];
}
